const express = require('express');
const app = express();

// Optional Postgres pool. We require lazily so the app still boots in
// environments where `pg` isn't installed; in that case the healthz
// probe reports the DB as unreachable (503) rather than crashing.
let pool = null;
try {
  // eslint-disable-next-line global-require
  const { Pool } = require('pg');
  pool = new Pool({ connectionString: process.env.DATABASE_URL });
} catch (err) {
  // `pg` not available — pingDb() will treat this as a failed check.
}

/**
 * Returns true if Postgres responds to a trivial query.
 * Override `app.locals.pingDb` in tests to simulate DB up/down.
 */
async function pingDb() {
  if (!pool) return false;
  const client = await pool.connect();
  try {
    await client.query('SELECT 1');
    return true;
  } finally {
    client.release();
  }
}

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Kubernetes readiness probe: 200 when we can reach Postgres, 503 otherwise.
app.get('/healthz', async (req, res) => {
  const check = app.locals.pingDb || pingDb;
  try {
    const ok = await check();
    if (ok) {
      return res.status(200).json({ db: 'ok' });
    }
    return res.status(503).json({ db: 'unavailable' });
  } catch (err) {
    return res.status(503).json({ db: 'unavailable' });
  }
});

